import java.util.*;

class Solution {
  private static final long MOD = 1_000_000_007L;

  public int countKSubsequencesWithMaxBeauty(String s, int k) {
    int[] frequency = new int[26];
    for (int i = 0; i < s.length(); i++) frequency[s.charAt(i) - 'a']++;
    Arrays.sort(frequency);
    if (k > 26 || frequency[26 - k] == 0) return 0;
    int threshold = frequency[26 - k], greater = 0, available = 0;
    long product = 1;
    for (int value : frequency) {
      if (value > threshold) {
        greater++;
        product = product * value % MOD;
      } else if (value == threshold) available++;
    }
    int needed = k - greater;
    product = product * choose(available, needed) % MOD;
    for (int i = 0; i < needed; i++) product = product * threshold % MOD;
    return (int) product;
  }

  private long choose(int n, int r) {
    long result = 1;
    for (int i = 1; i <= r; i++) {
      result = result * (n - r + i) % MOD;
      result = result * modInverse(i) % MOD;
    }
    return result;
  }

  private long modInverse(long value) {
    long result = 1, exponent = MOD - 2;
    while (exponent > 0) {
      if ((exponent & 1) != 0) result = result * value % MOD;
      value = value * value % MOD;
      exponent >>= 1;
    }
    return result;
  }
}
